'use strict';

// Build assets are embedded here as base64 instead of being read from
// the assets/ folder at runtime. On Vercel, a dynamic fs.readFileSync(path)
// call is invisible to the deployment bundler, so the assets/*.jpg files
// were silently left out of the deployed function and every photo send
// was failing -> falling back to plain text. Embedding the bytes directly
// in this module guarantees they ship with the function every time,
// regardless of bundler file-tracing behaviour.

const ASSETS = {
  "raven-response.jpg": Buffer.from(
    "",
    "base64"
  ),
  "raven-build-success.jpg": Buffer.from(
    "",
    "base64"
  ),
  "raven-goodbye.jpg": Buffer.from(
    "",
    "base64"
  ),
  "raven-welcome.jpg": Buffer.from(
    "",
    "base64"
  ),
};

module.exports = ASSETS;
